تنفيذ استراتيجية Stale-While-Revalidate باستخدام Kotlin Flow و Room:
```kotlin
class ArticleRepositoryImpl @Inject constructor(
    private val articleDao: ArticleDao,
    private val apiService: ArticleApiService
) : ArticleRepository {

    // Stale-While-Revalidate: ينبعث الكاش فوراً ثم يتم التحديث في الخلفية:
    override fun getArticles(): Flow<Resource<List<Article>>> = flow {
        // 1. بث النسخة المخزنة في الكاش فوراً (Stale Data):
        val cachedArticles = articleDao.getAllArticles().first()
        if (cachedArticles.isNotEmpty()) {
            emit(Resource.Success(data = cachedArticles.map { it.toDomain() }, isStale = true))
        } else {
            emit(Resource.Loading)
        }

        // 2. محاولة إعادة التحقق والتحديث من الشبكة في الخلفية (Revalidate):
        try {
            val freshArticles = apiService.fetchArticles()
            // حفظ البيانات الحديثة في Room:
            articleDao.updateAllArticles(freshArticles.map { it.toEntity() })
            // بث النسخة الحديثة بعد التحديث:
            emit(Resource.Success(data = freshArticles.map { it.toDomain() }, isStale = false))
        } catch (e: Exception) {
            // لو فشلت الشبكة، يظل المستخدم يشاهد بيانات الكاش مع تنبيه خفيف:
            if (cachedArticles.isEmpty()) {
                emit(Resource.Error(e.message ?: "Network error"))
            }
        }
    }
}
```

التنفيذ الكامل والآمن لـ Interceptor و Authenticator في OkHttp:
```kotlin
// 1. Auth Interceptor: يضيف التوكن الحالي لكل طلب:
class AuthHeaderInterceptor(private val tokenManager: TokenManager) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val token = tokenManager.getAccessToken()
        val request = if (token != null) {
            chain.request().newBuilder()
                .header("Authorization", "Bearer $token")
                .build()
        } else {
            chain.request()
        }
        return chain.proceed(request)
    }
}

// 2. OkHttp Authenticator: يتعامل مع 401 ويعيد المحاولة بالتوكن الجديد:
class TokenAuthenticator(
    private val tokenManager: TokenManager,
    private val authService: RefreshAuthService // يستخدم OkHttpClient مستقل بدون Authenticator!
) : Authenticator {
    override fun authenticate(route: Route?, response: Response): Request? {
        // حماية 1: منع الحلقات اللانهائية لو فشل الطلب أكثر من مرتين:
        if (responseCount(response) >= 2) return null

        // حماية 2: التزامن لمنع سباق الطلبات المتزامنة (Mutex / Synchronized):
        synchronized(this) {
            val currentToken = tokenManager.getAccessToken()
            // لو كان هناك طلب سابق قام بالفعل بالتجديد:
            val requestToken = response.request.header("Authorization")?.removePrefix("Bearer ")
            val validToken = if (currentToken != requestToken && currentToken != null) {
                currentToken // استخدام التوكن الجديد فوراً بدون طلب refresh إضافي
            } else {
                // طلب تجديد حقيقي:
                val newTokens = authService.refreshTokenBlocking(tokenManager.getRefreshToken())
                if (newTokens != null) {
                    tokenManager.saveTokens(newTokens.access, newTokens.refresh)
                    newTokens.access
                } else {
                    tokenManager.clearSessionAndForceLogout()
                    return null // إلغاء المحاولة وتسجيل الخروج
                }
            }

            // إعادة إرسال الطلب الأصلي بالتوكن المحدث:
            return response.request.newBuilder()
                .header("Authorization", "Bearer $validToken")
                .build()
        }
    }

    private fun responseCount(response: Response): Int {
        var result = 1
        var prior = response.priorResponse
        while (prior != null) { result++; prior = prior.priorResponse }
        return result
    }
}
```

تنفيذ بروتوكول Single-Flight مع فحص التوكن المزدوج لمنع سباق التجديد:
```kotlin
class SafeTokenManager @Inject constructor(
    private val tokenStorage: SecureTokenStorage,
    private val refreshApi: RefreshApi
) {
    private val refreshMutex = Mutex()

    suspend fun getOrRefreshValidToken(failedToken: String?): Result<String> {
        // قفل متزامن يمنع أي خيط آخر من بدء طلب تجديد جديد:
        refreshMutex.withLock {
            val currentToken = tokenStorage.getAccessToken()

            // الفحص المزدوج الحاسم (Double-Check):
            // لو خيط آخر قام بالتجديد أثناء انتظار هذا الخيط في الطابور:
            if (currentToken != null && currentToken != failedToken) {
                // التوكن تم تجديده بالفعل! نرجع التوكن الجديد فوراً بدون لمس السيرفر:
                return Result.success(currentToken)
            }

            // إذا كنا نحن الخيط الأول: ننفذ طلب تجديد واحد فقط (Single-Flight):
            val refreshToken = tokenStorage.getRefreshToken() ?: return Result.failure(SessionExpiredException)

            return try {
                val response = refreshApi.refreshToken(refreshToken)
                tokenStorage.saveTokens(response.accessToken, response.newRefreshToken)
                Result.success(response.accessToken)
            } catch (e: Exception) {
                tokenStorage.clearSession()
                Result.failure(e)
            }
        }
    }
}
```

